-- mdsa-project-management-pty-ltd-bryntirion (owner)
UPDATE businesses SET description = 'MDSA Project Management Pty Ltd is a project and construction management consultancy that has operated from its Gauteng head office in Lukasrand, Pretoria, since the company was established in 1998. The firm provides project management, construction management, tenant coordination and client representation services to property developers, owners, investors and businesses undertaking commercial, industrial and retail construction projects. Its portfolio of completed work spans shopping centres, broader commercial developments and industrial projects, reflecting a focus on guiding builds from planning through to completion on behalf of clients who need an experienced representative overseeing contractors, timelines and budgets. Beyond its Pretoria base, MDSA has grown into a multi-regional practice with additional offices in KwaZulu-Natal and in Cape Town and the Cape Winelands, as well as a presence in Mauritius, allowing it to support clients with developments across different parts of South Africa and the wider region. This geographic spread, built up over more than two decades, underpins the firm''s experience managing projects for a range of property and construction stakeholders.', description_enriched_at = datetime('now') WHERE slug = 'mdsa-project-management-pty-ltd-bryntirion' AND description = 'MDSA Project Management has provided project management, construction management, tenant coordination and client representation services since 1998, covering industrial, commercial and retail developments both locally and abroad.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
