UPDATE businesses SET description = 'Molati Attorneys Inc is a legal practice serving clients in the greater Pretoria area, offering legal services that include assistance with deceased estates, conveyancing and other property matters, alongside general legal practice work. The firm acts for individuals, families and businesses who require legal representation and advisory support, guiding clients through the administration of estates, property transfers and registrations, and a range of everyday legal matters. Molati Attorneys Inc has been in operation for a number of years and continues to be listed as an active legal practice in current business directories. The firm has relocated from its earlier premises, and clients are advised to confirm its current office location and contact details directly with the practice before visiting, though its core legal services for estates, property and general advisory matters remain available to clients across the Pretoria and wider Tshwane area.', description_enriched_at = datetime('now') WHERE slug = 'molati-attorneys-inc-lynnwood-glen' AND description = 'Molati Attorneys Inc is a township-based law firm in Lynnwood Glen, Pretoria, practising since 2017 in conveyancing, litigation, insolvency, debt collection, government regulatory affairs and family law.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
