UPDATE businesses SET description = 'Montana Power Tools is a power-tool sales, repair and machine-workshop business serving the greater Pretoria area. The business sells power tools and provides servicing and repairs for a range of equipment, with its workshop also undertaking precision machining work. Montana Power Tools serves DIY customers, tradespeople, contractors and professional workshops who need tools sourced, serviced or repaired, positioning itself as a point of call for both retail purchases and technical repair work. Its combination of retail sales and an in-house machine workshop allows it to support customers beyond a simple point of sale, handling maintenance and repair needs for tools used in both home and commercial settings. The business is recognised as an accredited service agent for at least one major power-tool brand, reflecting its established repair and servicing capability in the Pretoria market.', description_enriched_at = datetime('now') WHERE slug = 'montana-power-tools-moregloed' AND description = 'Montana Power Tools is a machine workshop in Moregloed, Pretoria, repairing generators, welders, power tools and refrigerators, and stocking second-hand tools and demo models with free quotations.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
