UPDATE businesses SET description = 'Nando''s Lynnwood Lane is a branch of the flame-grilled PERi-PERi chicken chain, located at Shop 111 in the Lynnwood Lane Retail Centre on Lynnwood Road, Equestria, Pretoria. The restaurant serves the brand''s Portuguese-inspired menu, including chicken, burgers, wraps, pitas, rice or salad bowls, and a range of sides, as well as larger sharing meals suited to bigger groups. It caters to individuals, families and groups of diners, whether they are eating in, collecting a takeaway order or having food delivered. This branch offers dine-in, collection and delivery options, giving customers flexibility in how they receive their order. Positioned within the Lynnwood Lane Retail Centre, the restaurant serves the surrounding Equestria community and wider Pretoria area with the chain''s familiar range of flame-grilled chicken dishes and accompaniments, catering to everyday meals as well as takeaway orders for groups and families.', description_enriched_at = datetime('now') WHERE slug = 'nandos-lynnwood-lane-equestria' AND description = 'This Nando''s outlet in Lynnwood Lane Retail Centre serves the brand''s signature PERi-PERi chicken for dine-in, takeaway or delivery, with wheelchair-accessible parking, entrance and seating on site.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
