UPDATE businesses SET description = 'NP Engineering is a mechanical and electrical engineering company providing engineering solutions, installation, repair and maintenance services to customers across the Pretoria area. The company works with residential, commercial and industrial clients, handling engineering needs that range from installing new mechanical and electrical systems to repairing and maintaining existing equipment and infrastructure. Its services are aimed at keeping clients'' systems running reliably, covering both routine maintenance and ad hoc repair work as issues arise. NP Engineering operates beyond Pretoria alone, extending its engineering services throughout Gauteng, Limpopo and Mpumalanga, which allows it to support clients with operations or properties in different parts of these provinces. This regional reach, combined with its focus on mechanical and electrical engineering disciplines, positions the company as a service provider for customers needing ongoing technical support rather than a single once-off installation.', description_enriched_at = datetime('now') WHERE slug = 'np-engineering-riviera' AND description = 'NP Engineering is a mechanical and electrical engineering company offering air conditioning and refrigeration contracting services to domestic, commercial and industrial clients across Gauteng, Limpopo and Mpumalanga.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
